#!/bin/sh
# oppo-dv-mkv: Dolby Vision content mapping metadata that never reaches the TV in TV-led mode (bdpdrv1 kernel RAM
# patch, part of the Dolby Vision MKV fix). usage: on|off|status|check
# In TV-led Dolby Vision the player sends the picture untouched and, with every frame, the metadata the TV maps it
# with. The driver loses part of that metadata on the way (Oppo's code, any container, discs too):
#   CM 2.9  L5 (active area) is always dropped; the TV then ignores positive lift (L2 offset above neutral);
#           L1 is replaced by fixed values when its maximum is above the mastering display's;
#           positive lift is cut to neutral.                              3 instructions in update_md_for_hdmi
#   CM 4.0  the second extension block list of the RPU (L3 L8 L9 L10 L11 L254) is never read.
# The stub (source: dvcm.S) reads the CM 4.0 blocks and appends them to the HDMI metadata, and rewrites L5 for the
# frame the player really outputs (its own bars, scaling, zoom). A TV blanks everything outside the L5 area, also
# what the player draws there, so the area is widened, frame by frame, to take in the info bar, menus and subtitles
# shown outside it (the OSD planes' bitmaps are sampled). The picture itself is never changed.
# The stub lives in parse_cmd_line_option, a command line parser of Dolby's test harness that nothing calls.
# The code is at the same place in every known driver build (RU, USA, CXUHD, ...); only data moves. The stub's six
# data addresses are read from the driver on the player; everything relied on is checked by its bytes first.
export PATH=/bin:/sbin:/usr/bin:/usr/sbin:/usr/local/bin
grep -q "^bdpdrv1 .* 0x7e8d3000 " /proc/modules || { echo "bdpdrv1 not at 0x7e8d3000 (unsupported firmware)"; exit 1; }
# virtual -> physical through the kernel page tables (swapper pgd at PA 0x4000), then /dev/mem
u32(){ dd if=/dev/mem bs=4 skip=$(( $1 / 4 )) count=1 2>/dev/null | hexdump -v -e '1/4 "%u"'; }
pa(){ l1=$(u32 $((0x4000 + ($1 >> 20) * 4))); [ $((l1 & 3)) = 2 ] && { echo $(( (l1 & 0xfff00000) | ($1 & 0xfffff) )); return; }
      pte=$(u32 $(( (l1 & 0xfffffc00) + (($1 >> 12) & 0xff) * 4 ))); echo $(( (pte & 0xfffff000) | ($1 & 0xfff) )); }
rdm(){ dd if=/dev/mem bs=1 skip=$(pa $1) count=$2 2>/dev/null | hexdump -v -e "$2/1 \"%02x\""; }   # within one page
wrm(){ printf "$(echo $2 | sed 's/../\\x&/g')" | dd of=/dev/mem bs=1 seek=$(pa $1) conv=notrunc 2>/dev/null; }   # hex string
le(){ printf '%02x%02x%02x%02x' $(($1 & 255)) $(($1 >> 8 & 255)) $(($1 >> 16 & 255)) $(($1 >> 24 & 255)); }
CAVE=0x7eb53688; CEND=0x7eb53eec; CLEN=2148               # the stub: STUB + the six data addresses (LITS)
# hooks, site:stock:hooked, in the order they are switched on. The first wraps update_md_for_hdmi (L5); the rest:
# append to the HDMI metadata, generated metadata, parser -> metadata buffer, second list, unknown level, reset.
H="0x7eb5512c:9a0300eb:fcf9ffeb 0x7eb3ece0:d020c7e1:ed5200ea 0x7eb55134:2a0300eb:d5f9ffeb 0x7eb43eb0:f08fbde8:6e3e00ea 0x7eb48354:140094e5:d92c00ea 0x7eb48630:4a30d2e5:1b2c00ea 0x7eb4834c:4a00c5e5:cd2c00eb"
# CM 2.9, update_md_for_hdmi: keep L5; keep L1 as authored; keep positive lift
T="0x7eb56394:053042e2:063042e2 0x7eb563b4:2e00001a:2e0000ea 0x7eb564a8:1300001a:130000ea"
# code the patch relies on, address:bytes
FP="0x7e94fde0:20309fe50034d3e7 0x7e951e6c:20309fe5 0x7e951e80:040093e5960d40e2 0x7e952688:b830d4115330ea17 0x7e952cac:b432d4115330ec17 0x7e953118:ba32d4115330eb17 0x7e9532e0:be32d4115330ec17 0x7e953e9c:0330d0e50000a0e32332a0e1 0x7e9541f0:042090e55220f7e70222a0e1 0x7e954200:be31d0e1d333e1e7033e82e1 0x7e95438c:0c3090e55330f9e7 0x7e965950:18309fe53810a0e3 0x7e965960:0c0090e5 0x7e96fc28:20209f151400a01390232310 0x7e96fc3c:04309315 0x7e99126c:14309fe5000050e3 0x7eb3ebf8:f74f2de90060a0e1 0x7eb3ecdc:e0ffffea 0x7eb3ece4:303083e3 0x7eb43eac:5effffea 0x7eb43eb4:0030d1e5 0x7eb442d8:f0472de90370a0e1 0x7eb46310:70402de90030a0e1 0x7eb46690:100050e370402de9 0x7eb4692c:0010a0e108402de9 0x7eb480fc:f84f2de9014880e2 0x7eb48348:000050e3 0x7eb48350:0200001a 0x7eb48358:000069e0 0x7eb4862c:b9ffffea 0x7eb48634:018048e2 0x7eb48648:0b0056e10300002a 0x7eb55128:0100001a 0x7eb55130:000000ea 0x7eb55138:78319fe5 0x7eb55de4:30402de90320a0e3 0x7eb55f9c:f04f2de90080a0e1 0x7eb56390:4b20d6e5 0x7eb56398:7330efe6 0x7eb563b0:9c050ce0 0x7eb563b8:003098e5 0x7eb564a4:0230cce5 0x7eb564ac:043098e5 0x7eb5a4bc:20319fe5 0x7eb5a4e8:242093e5"
# where the driver's own code holds the six data addresses, address:RU value
ANCH="0x7e94fe08:0x7ede0aac 0x7e991288:0x7ed2bbf0 0x7eb5a5e4:0x7eea45e8 0x7e965970:0x7ede1740 0x7e96fc50:0x7ede562c 0x7e951e94:0x7ede1114"


state(){
  for e in $FP; do x=${e#*:}; [ "$(rdm ${e%%:*} $((${#x} / 2)))" = $x ] || { echo "unexpected code at ${e%%:*}"; return 1; }; done
  LITS=; d0=
  for e in $ANCH; do v=$(u32 $(pa ${e%%:*})); d=$((v - ${e#*:})); [ -z "$d0" ] && d0=$d
    [ $d = $d0 ] && [ $d -ge -65536 ] && [ $d -le 65536 ] || { echo "unexpected data address at ${e%%:*}"; return 1; }; LITS=$LITS$(le $v); done
  # the stub reads the OSD bitmaps through the kernel's linear mapping, below physical 0x3f000000
  [ "$(pa 0x80100000)" = $((0x100000)) ] && [ "$(pa 0xbefffffc)" = $((0x3efffffc)) ] || { echo "unexpected kernel memory layout"; return 1; }
  n=0; p=0; o=0
  for e in $H $T; do a=${e%%:*}; r=${e#*:}; w=$(rdm $a 4); n=$((n + 1))
    case $w in ${r%%:*}) ;; ${r#*:}) p=$((p + 1));;
    *) t=$(bt $a $w) && [ $t -ge $((CAVE)) ] && [ $t -lt $((CEND + 256)) ] && o=$((o + 1)) || { echo "unexpected $w at $a"; return 1; };; esac; done
  c=$(rdm $CAVE $CLEN)
  if [ "$c" = $STUB$LITS ] && [ $o = 0 ]; then [ $p = $n ] && echo on || { [ $p = 0 ] && echo off || echo partial; }
  elif [ "$c" = $CORIG ] && [ $p = 0 ] && [ $o = 0 ]; then echo off
  elif [ $((p + o)) -gt 0 ] && [ "$c" != $CORIG ]; then echo other    # another version of this patch is on
  else echo "unexpected bytes in the cave at $CAVE"; return 1; fi; }
# where a branch word $2 at $1 goes
bt(){ case $2 in ??????ea|??????eb) ;; *) return 1;; esac; q=$((0x$(echo $2 | sed 's/\(..\)\(..\)\(..\)../\3\2\1/')))
      [ $q -ge $((0x800000)) ] && q=$((q - 0x1000000)); echo $(($1 + 8 + q * 4)); }
rev(){ r=; for e in $*; do r="$e $r"; done; echo $r; }
off(){ for e in $(rev $H $T); do r=${e#*:}; wrm ${e%%:*} ${r%%:*}; done; wrm $CAVE $CORIG; }
s=$(state) || { echo "$s, nothing written"; exit 1; }
state >/dev/null   # sets LITS in this shell
case "$1" in
check) echo "compatible ($s)";;
on)  [ $s = on ] && { echo "already on"; exit 0; }
     [ $s = off ] || off
     wrm $CAVE $STUB$LITS; [ "$(rdm $CAVE $CLEN)" = $STUB$LITS ] || { echo "cave write failed"; exit 1; }
     for e in $H $T; do r=${e#*:}; wrm ${e%%:*} ${r#*:}; done
     s=$(state); echo "on ($s)"; [ "$s" = on ] || exit 1;;
off) [ $s = off ] && [ "$(rdm $CAVE $CLEN)" = $CORIG ] && { echo "already off"; exit 0; }
     off; s=$(state); echo "off ($s)"; [ "$s" = off ] || exit 1;;
*)   echo $s;;
esac
